    fn permission_actions_require_focused_submitter_authority() {
        let pending = vec![PendingPermission {
            permission_id: "permission-a".into(),
            session_id: "session-a".into(),
            tool: "bash".into(),
            reason: "run check".into(),
            args_summary: String::new(),
            deciding: false,
        }];

        assert_eq!(
            permission_action_state(
                Some("permission-a"),
                "request-a",
                Some("session-a"),
                Some("session-a"),
                Some("request-a"),
                true,
                &pending,
            ),
            Some(false)
        );
        assert_eq!(
            permission_action_state(
                Some("permission-a"),
                "request-a",
                Some("session-a"),
                Some("session-b"),
                Some("request-a"),
                true,
                &pending,
            ),
            None
        );
        assert_eq!(
            permission_action_state(
                Some("permission-a"),
                "request-a",
                Some("session-a"),
                Some("session-a"),
                Some("request-a"),
