            ),
            request(
                "failed-2",
                None,
                RequestSnapshotState::Errored,
                "2026-07-14T04:00:00Z",
            ),
            request(
                "failed-3",
                None,
                RequestSnapshotState::Errored,
                "2026-07-14T03:00:00Z",
            ),
            request(
                "failed-4",
                None,
                RequestSnapshotState::Errored,
                "2026-07-14T02:00:00Z",
            ),
            request(
                "done",
                None,
                RequestSnapshotState::Completed,
                "2026-07-14T06:00:00Z",
            ),
            request(
                "cancelled",
                None,
                RequestSnapshotState::Cancelled,
                "2026-07-14T07:00:00Z",
            ),
        ];
