    fn focused_sorts_first_and_newer_background_sorts_next() {
        let sessions = vec![
            session("new", "New", "/new", "2026-07-14T12:00:00Z"),
            session("focused", "Focused", "/focus", "2020-01-01T00:00:00Z"),
