+  .has-workspace-open .ocean-brand {
+    display: none;
+  }
+}
+
+@media (max-width: 840px) {
+  .is-titlebar .ocean-brand__word {
+    display: none;
+  }
+}
+
+@media (max-width: 720px) {
+  /* compact.css is later in the cascade; higher specificity preserves the
+     native traffic-light inset at the supported minimum. */
+  main.ocean-surface.is-titlebar .ocean-header {
+    padding-left: var(--titlebar-inset);
+  }
+
+  .has-workspace-open .ocean-brand {
+    display: none;
+  }
+}
+
 .ocean-header__right {
   display: flex;
   align-items: center;
