+.component-interactive-plot {
+  display: grid;
+  gap: 14px;
+}
+
+.component-interactive-plot--error {
+  gap: 4px;
+  color: var(--fg-2);
+  font-size: 13px;
+}
+
+.component-interactive-plot--error strong {
+  color: var(--fg);
+}
+
+.interactive-plot__title {
+  margin: 0;
+}
+
+.interactive-plot__description {
+  max-width: 72ch;
+  margin: -8px 0 0;
+  color: var(--fg-2);
+  font-size: 13px;
+  line-height: 1.5;
+}
+
+.interactive-plot__graph {
+  min-width: 0;
+  padding: 12px;
+  background: var(--bg-well);
+  box-shadow: var(--well);
+  border-radius: var(--radius);
+}
+
+.interactive-plot__plot-area {
+  position: relative;
+  min-width: 0;
+  padding: 12px 0 14px 42px;
+}
+
+.interactive-plot__plot-area svg {
+  display: block;
+  width: 100%;
+  height: clamp(170px, 32vw, 260px);
+  overflow: visible;
+}
+
+.interactive-plot__grid {
+  stroke: var(--border);
+  stroke-width: 0.5;
+  vector-effect: non-scaling-stroke;
+}
+
+.interactive-plot__line {
+  fill: none;
+  stroke: var(--accent);
+  stroke-width: 2;
+  stroke-linecap: round;
+  stroke-linejoin: round;
+  vector-effect: non-scaling-stroke;
+}
+
+.interactive-plot__line--2 { stroke: var(--info); }
+.interactive-plot__line--3 { stroke: var(--ok); }
+.interactive-plot__line--4 { stroke: var(--warn); }
+.interactive-plot__line--5 { stroke: var(--err); }
+.interactive-plot__line--6 { stroke: var(--accent-bright); }
+
+.interactive-plot__legend {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 6px 14px;
+  padding: 10px 0 0 42px;
+  color: var(--fg-2);
+  font-size: 10px;
+}
+
+.interactive-plot__legend-item {
+  display: inline-flex;
+  align-items: center;
+  gap: 5px;
+  min-width: 0;
+}
+
+.interactive-plot__legend-item > span {
+  overflow: hidden;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__legend-swatch {
+  width: 14px;
+  height: 3px;
+  flex: 0 0 14px;
+  border-radius: var(--radius-pill);
+  background: var(--accent);
+}
+
+.interactive-plot__legend-swatch--2 { background: var(--info); }
+.interactive-plot__legend-swatch--3 { background: var(--ok); }
+.interactive-plot__legend-swatch--4 { background: var(--warn); }
+.interactive-plot__legend-swatch--5 { background: var(--err); }
+.interactive-plot__legend-swatch--6 { background: var(--accent-bright); }
+
+.interactive-plot__y-label,
+.interactive-plot__x-axis,
+.interactive-plot__y-max,
+.interactive-plot__y-min {
+  color: var(--fg-3);
+  font-family: var(--mono);
+  font-size: 10px;
+}
+
+.interactive-plot__y-label {
+  min-height: 14px;
+  padding-left: 42px;
+}
+
+.interactive-plot__y-max,
+.interactive-plot__y-min {
+  position: absolute;
+  left: 0;
+  width: 36px;
+  overflow: hidden;
+  text-align: right;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__y-max { top: 8px; }
+.interactive-plot__y-min { bottom: 10px; }
+
+.interactive-plot__x-axis {
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  gap: 8px;
+  padding-left: 42px;
+}
+
+.interactive-plot__x-axis span:last-child {
+  text-align: right;
+}
+
+.interactive-plot__error {
+  padding: 28px 12px;
+  color: var(--err);
+  font-size: 12px;
+  text-align: center;
+}
+
+.interactive-plot__metrics {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
+  gap: 8px;
+}
+
+.interactive-plot__metric {
+  display: grid;
+  gap: 4px;
+  min-width: 0;
+  padding: 10px 12px;
+  background: var(--bg-well);
+  box-shadow: var(--well);
+  border-radius: var(--radius);
+}
+
+.interactive-plot__metric span {
+  overflow: hidden;
+  color: var(--fg-3);
+  font-size: 11px;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__metric strong {
+  overflow: hidden;
+  color: var(--fg);
+  font-family: var(--mono);
+  font-size: 15px;
+  text-overflow: ellipsis;
+  white-space: nowrap;
+}
+
+.interactive-plot__controls {
+  display: grid;
+  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
+  gap: 12px 16px;
+}
+
+.interactive-plot__control {
+  min-width: 0;
+  margin: 0;
+  padding: 0;
+  border: 0;
+}
+
+.interactive-plot__control legend {
+  width: 100%;
+  margin-bottom: 6px;
+  color: var(--fg-2);
+  font-size: 12px;
+}
+
+.interactive-plot__control-row {
+  display: grid;
+  grid-template-columns: minmax(100px, 1fr) auto;
+  align-items: center;
+  gap: 10px;
+}
+
+.interactive-plot__range {
+  width: 100%;
+  min-width: 0;
+  height: 28px;
+  margin: 0;
+  accent-color: var(--accent);
+  cursor: pointer;
+  touch-action: pan-y;
+}
+
+.interactive-plot__number-wrap {
+  display: flex;
+  align-items: center;
+  gap: 5px;
+  min-width: 86px;
+  padding: 5px 7px;
+  background: var(--bg-well);
+  box-shadow: var(--well);
+  border-radius: var(--radius-sm);
+}
+
+.interactive-plot__number {
+  width: 7ch;
+  min-width: 0;
+  padding: 0;
+  border: 0;
+  outline: 0;
+  background: transparent;
+  color: var(--fg);
+  font: 12px/1.4 var(--mono);
+  text-align: right;
+}
+
+.interactive-plot__number-wrap:focus-within {
+  box-shadow: var(--focus-ring), var(--well);
+}
+
+.interactive-plot__unit {
+  color: var(--fg-3);
+  font-family: var(--mono);
+  font-size: 10px;
+}
+
+.interactive-plot__sr-only {
+  position: absolute;
+  width: 1px;
+  height: 1px;
+  padding: 0;
+  margin: -1px;
+  overflow: hidden;
+  clip: rect(0, 0, 0, 0);
+  white-space: nowrap;
+  border: 0;
+}
+
+@media (max-width: 560px) {
+  .component-interactive-plot {
+    padding: 12px;
+  }
+
+  .interactive-plot__graph {
+    padding: 8px;
+  }
+
+  .interactive-plot__plot-area svg {
+    height: 170px;
+  }
+
+  .interactive-plot__controls {
+    grid-template-columns: minmax(0, 1fr);
+  }
+}
+
+@media (prefers-reduced-motion: reduce) {
+  .interactive-plot__line {
+    transition: none;
+  }
+}
+
 /* ---- Timeline ---------------------------------------------------------- */
 .component-timeline {
   padding: 16px;
